('200026','200','Locação de imóveis localizados nas zonas reabilitadas','Locação de imóveis localizados nas zonas reabilitadas, pelo prazo de 5 (cinco) anos, contado da data de expedição do habite-se, e relacionados a projetos de reabilitação urbana de zonas históricas e de áreas críticas de recuperação e reconversão urbanística dos Municípios ou do Distrito Federal, a serem delimitadas por lei municipal ou distrital, observado o art. 158 da Lei Complementar nº 214, de 2025.',80,80,'2026-01-01'::date,NULL,false,'{"tipoAliquota":"Padrão","indTribRegular":0,"indCredPresOper":0,"indMonoPadrao":0,"indMonoReten":0,"indMonoRet":0,"indMonoDif":0,"tpRBSN":9,"indNFe":0}'::jsonb,'IT2025.002-v1.60-2026-06-22','2026-06-22'::date,'https://www.planalto.gov.br/ccivil_03/leis/lcp/lcp214.htm#art158'),
('200027','200','Operações de locação, cessão onerosa e arrendamento de bens imóveis','Operações de locação, cessão onerosa e arrendamento de bens imóveis, observado o art. 261 da Lei Complementar nº 214, de 2025.',70,70,'2026-01-01'::date,NULL,false,'{"tipoAliquota":"Padrão","indTribRegular":0,"indCredPresOper":0,"indMonoPadrao":0,"indMonoReten":0,"indMonoRet":0,"indMonoDif":0,"tpRBSN":1,"indNFe":0}'::jsonb,'IT2025.002-v1.60-2026-06-22','2026-06-22'::date,'https://www.planalto.gov.br/ccivil_03/leis/lcp/lcp214.htm#art261'),
